function hall(c,images,f,t,omitFront=false){hallBackground(c,images,f,t,wartimeRevealPose(t).roomZoom);silhouettes(c,images,f,t);revealBlue(c,f,t);if(t>=488.1){const a=span(t,488.1,489.8),b=span(t,489.1,491),p=wartimeRevealPose(t);if(f.wartimeFullSources.wartBrothers||f.wartimeSourceBindings.wartBrothers){if(!omitFront)sprite(c,images,f,'wartBrothers',t,[-640+a*710,50,820,0],{mono:f.wartimeCharacterMono});}else{layer(c,f,'wartBrothers',t,[0,0,960,540],()=>{c.translate(-480,-270);const inner={...f,wartimeCameraX:0,wartimeCameraY:0,wartimeCameraZoom:0};sprite(c,images,inner,'wartBrotherA',t,[t>=494.35?p.rearX:-850+a*690,0,650,0],{mono:f.wartimeCharacterMono});if(!omitFront)sprite(c,images,inner,'wartBrotherB',t,[t>=494.35?p.frontX:1200-b*650,t>=494.35?p.frontY:35,t>=494.35?p.frontWidth:700,0],{mono:f.wartimeCharacterMono});});}}if(t<484.2){c.fillStyle=`rgba(0,0,0,${1-span(t,483.5,484.2)})`;c.fillRect(0,0,960,540);}}

export function wartimeMoneyPose(index,t,f=wartimeDefaults){const i=index,cohort=Math.floor(i/24),birth=cohort*.17+(i%6)*.012,age=(t-496)*f.wartimeMoneySpeed-birth,angle=-Math.PI*.9+(i%13)/12*Math.PI*.8,speed=f.wartimeMoneyLaunchSpeed*(.68+(i*7%11)/25),depth=.48+(i*7%9)*.14,vx=Math.cos(angle)*speed*f.wartimeMoneyBurst,vy=Math.sin(angle)*speed*f.wartimeMoneyBurst;return{age,x:480+(i%3-1)*18+vx*age+Math.sin(age*3+i)*12*age,y:100+vy*.62*age+.5*f.wartimeMoneyGravity*age*age,depth,rotation:i*.71+age*(i%2?-.9:1.1),flip:.17+.83*Math.abs(Math.cos(i*.9+age*2.2))};}
function banknotes(c,f,t){layer(c,f,'banknotes',t,[0,0,960,540],()=>{for(let i=0;i<f.wartimeNoteCount;i++){const p=wartimeMoneyPose(i,t,f);if(p.age<0||p.age>3.4)continue;c.save();c.translate(p.x-480,p.y-270);c.rotate(p.rotation);c.scale(p.depth*p.flip,p.depth);c.filter=`blur(${1.2+Math.max(0,p.depth-1.2)*2.2}px)`;c.fillStyle='#b8bba0';c.fillRect(-47,-20,94,40);c.strokeStyle='#555e42';c.lineWidth=1.3;c.strokeRect(-44,-17,88,34);c.strokeRect(-40,-14,80,28);c.beginPath();c.ellipse(0,0,11,15,0,0,Math.PI*2);c.stroke();for(let j=-32;j<35;j+=4){c.beginPath();c.moveTo(j,-11);c.bezierCurveTo(j+6,-6,j-6,6,j,11);c.stroke();}c.fillStyle='#596148';c.font='800 11px Arial';c.fillText('10',-39,-3);c.fillText('10',26,12);c.restore();}});}
function stadium(c,images,f,t){const pass=span(t,499.3,500.5),up=span(t,502.5,503.7);c.save();c.filter='blur(2px) brightness(1.18) saturate(.55)';plate(c,images,f,'wartStadiumSky',t,1.05);c.restore();plate(c,images,f,'wartStadium',t,1.06+pass*.12,up*300);revealBlue(c,f,t);sprite(c,images,f,'wartSeated',t,[mix(590,240,pass),mix(160,90,pass)+up*550,mix(330,580,pass),0],{mono:f.wartimeCharacterMono});sprite(c,images,f,'wartSuccess',t,[mix(180,-1700,pass),mix(30,-300,pass)+up*550,mix(850,1900,pass),0],{mono:f.wartimeCharacterMono,alpha:1-span(t,500.2,500.5)});
 if(t<496.3){const p=wartimeRevealPose(t),id=f.wartimeFullSources.wartBrothers||f.wartimeSourceBindings.wartBrothers?'wartBrothers':'wartBrotherB',body=[p.frontX,p.frontY,p.frontWidth,0],mask=Object.assign(document.createElement('canvas'),{width:960,height:540}),mc=mask.getContext('2d');sprite(mc,images,f,id,t,body,{mono:f.wartimeCharacterMono});const a=mc.getImageData(0,0,960,540).data;c.save();c.beginPath();c.moveTo(0,0);for(let y=0;y<540;y+=3){let edge=-1;for(let x=959;x>=0;x--)if(a[(y*960+x)*4+3]>230){edge=x;break;}c.lineTo(edge>=0?edge-1:clamp(p.frontX+p.frontWidth*.64,0,960),y);}c.lineTo(0,540);c.closePath();c.clip();hall(c,images,f,t,true);c.restore();c.drawImage(mask,0,0);}if(t>=496&&t<499.4)banknotes(c,f,t);

}
export function wartimeAtlasFrame(images,prefix,index,cols,rows){const per=cols*rows,i=Math.max(0,Math.floor(index)),im=images[prefix+Math.floor(i/per)];return im?.width?{im,x:i%cols*im.width/cols,y:Math.floor(i%per/cols)*im.height/rows,w:im.width/cols,h:im.height/rows}:null;}
function drawAtlas(c,a,x,y,w,h){if(a)c.drawImage(a.im,a.x,a.y,a.w,a.h,x,y,w,h);}
function blast(c,images,f,t){const age=t-503.4;if(age<0||age>4.5)return;const frame=wartimeAtlasFrame(images,'wartBlastFrame',Math.min(95,age*24),4,4);layer(c,f,'explosion',t,[0,0,960,540],(x,y)=>{c.filter+=(c.filter==='none'?'':' ')+`brightness(${f.wartimeBlastExposure})`;if(f.wartimeFullSources.wartExplosion||f.wartimeSourceBindings.wartExplosion){const im=image(images,f,'wartExplosion');if(im)c.drawImage(im,x-100,y-180,1160,900);}else drawAtlas(c,frame,x-100,y-180,1160,900);},{alpha:(1-span(t,506.6,507.7))*f.wartimeSmoke});if(age<.22){c.save();c.globalCompositeOperation='screen';c.globalAlpha=(1-age/.22)*.35;c.fillStyle='#ffd69c';c.fillRect(0,0,960,540);c.restore();}}
export function wartimeFlashAmount(t,f=wartimeDefaults){return f.wartimeAircraftFlash*(.82*Math.exp(-Math.pow((t-507.08)/.075,2))+.65*Math.exp(-Math.pow((t-507.32)/.09,2))+.68*Math.exp(-Math.pow((t-508.43)/.13,2)));}
export function wartimeAircraftPose(t,f=wartimeDefaults){const age=t-506.4,enter=span(t,506.4,507.35),exit=span(t,509.35,510.4),bank=(-3+Math.sin(age*1.85)*f.wartimeAircraftBank)*enter-exit*17,yaw=Math.sin(age*1.45-.6)*f.wartimeAircraftYaw*enter;return{x:145-age*9-exit*28,y:150+Math.sin(age*1.7)*7-exit*650,w:650+Math.sin(age*.8)*9,bank,yaw,enter,exit,phase:(t-506.4)*f.wartimePropellerRPM*Math.PI/30};}
export function wartimePropellerSample(phase,blade=0){const a=phase+blade*Math.PI*2/3;return{x:Math.cos(a)*7,y:Math.sin(a)*66};}
function aircraft(c,images,f,t){const pose=wartimeAircraftPose(t,f),flash=wartimeFlashAmount(t,f);c.save();c.filter='brightness(1.22) saturate(1.3)';sky(c,images,f,t);c.restore();layer(c,f,'aircraft-glow',t,[0,0,960,540],(x,y,w,h)=>{c.globalCompositeOperation='screen';const g=c.createRadialGradient(90,-170,5,90,-170,650);g.addColorStop(0,`rgba(255,18,8,${.16+flash*.55})`);g.addColorStop(.55,`rgba(210,0,10,${.06+flash*.2})`);g.addColorStop(1,'#f000');c.fillStyle=g;c.fillRect(x,y,w,h);});const im=image(images,f,'wartAircraft');if(im){const W=pose.w,H=W*im.height/im.width;layer(c,f,'wartAircraft',t,[pose.x,pose.y,W,H],(x,y)=>{c.scale(Math.cos(pose.yaw*Math.PI/180),1+Math.sin(pose.yaw*Math.PI/180)*.045);c.filter+=(c.filter==='none'?'':' ')+`brightness(${1+flash*.6})`;for(let j=0;j<28;j++){const u=j/28,shear=(u-.5)*Math.sin(pose.yaw*Math.PI/180)*H*.16;c.drawImage(im,u*im.width,0,im.width/28,im.height,x+u*W,y+shear,W/28+.65,H);}
 const inner={...f,wartimeCameraX:0,wartimeCameraY:0,wartimeCameraZoom:0},hubY=y+H*.49-.482*Math.sin(pose.yaw*Math.PI/180)*H*.16;layer(c,inner,'propeller',t,[x+W*.018-10,hubY-70,20,140],()=>{c.save();c.fillStyle='#bfcbd92b';c.beginPath();c.ellipse(0,0,8,66,0,0,Math.PI*2);c.fill();for(let k=0;k<7;k++){const ph=pose.phase-k*.135;c.globalAlpha=.16;for(let blade=0;blade<3;blade++){const p=wartimePropellerSample(ph,blade);c.fillStyle='#e4e9e9';c.beginPath();c.moveTo(-2,-3);c.lineTo(p.x-1.8,p.y);c.lineTo(p.x+1.8,p.y);c.lineTo(2,3);c.closePath();c.fill();}}c.globalAlpha=1;c.fillStyle='#44494d';c.beginPath();c.ellipse(0,0,4,5,0,0,Math.PI*2);c.fill();c.restore();},{alpha:1,blur:.45});},{alpha:pose.enter,rotation:pose.bank});}if(t<507.8)blast(c,images,f,t);}

function emblem(c,f,t,y){layer(c,f,'emblem',t,[245,y,470,470],()=>{c.fillStyle='#a70a14';c.beginPath();c.arc(0,0,230,0,Math.PI*2);c.fill();c.rotate(-Math.PI/4);c.strokeStyle='#08090a';c.lineWidth=53;c.lineCap='butt';for(let i=0;i<4;i++){c.save();c.rotate(i*Math.PI/2);c.beginPath();c.moveTo(0,0);c.lineTo(0,-140);c.lineTo(130,-140);c.stroke();c.restore();}},{alpha:span(t,512.6,514)*.9});}
export function wartimeFactoryPose(t,f=wartimeDefaults){return{zoom:1+span(t,512.3,518.1)*f.wartimeFactoryZoom,rise:span(t,510.4,512.3)};}
function exterior(c,images,f,t){sky(c,images,f,t);const p=wartimeFactoryPose(t,f);layer(c,f,'factory-camera',t,[0,0,960,540],()=>{c.translate(-480,-270);c.translate(480,450);c.scale(p.zoom,p.zoom);c.translate(-480,-450);const inner={...f,wartimeCameraX:0,wartimeCameraY:0,wartimeCameraZoom:0};emblem(c,inner,t,-25);layer(c,inner,'wartGround',t,[-100,405,1160,160],(x,y,w,h)=>{const im=images[f.wartimeSourceBindings.wartGround||'wartGround'];if(im?.width)c.drawImage(im,0,im.height*.64,im.width,im.height*.36,x,y,w,h);},{mono:.9});layer(c,inner,'ground-shade',t,[-100,405,1160,160],(x,y,w,h)=>{c.fillStyle=`rgba(1,5,9,${1-f.wartimeGroundExposure})`;c.fillRect(x,y,w,h);});sprite(c,images,inner,'wartBuilding',t,[200,600-p.rise*460,540,0],{mono:1});});}
export function wartimeWorkerPose(t,f=wartimeDefaults){const enter=span(t,519,519+f.wartimeWorkerEntryDuration),z=mix(1.15,.85,span(t,520.5,523)),w=700*z;return{x:480-w/2,y:mix(610,56,enter),w,enter};}
function factory(c,images,f,t){hallBackground(c,images,f,t,1.08);const p=wartimeWorkerPose(t,f);sprite(c,images,f,'wartWorker',t,[p.x,p.y,p.w,0]);if(t<519.8){const shift=span(t,518.1,519.8)*560;c.save();c.beginPath();c.rect(0,0,960,540-shift);c.clip();c.translate(0,-shift);exterior(c,images,f,518.1);c.restore();}}
export function wartimePortraitGeometry(t,f,aspect=1.3333333333){const q=span(t,523,525.7),W=mix(7600,850,q),H=W*aspect,rx=mix(480,475,q),ry=mix(270,225,q);return{W,H,x:rx-f.wartimeEyeX*W,y:ry-f.wartimeEyeY*H,rx,ry,r:mix(560,W*.014,span(t,523,524))};}
function portrait(c,images,f,t,background=true){if(background){c.save();c.filter='blur(2px)';plate(c,images,f,'wartHall',t,1.2);c.restore();}const im=image(images,f,'wartPortrait');if(!im)return;const g=wartimePortraitGeometry(t,f,im.height/im.width),{W,H,x,y,r}=g;layer(c,f,'wartPortrait',t,[x,y,W,H],(X,Y)=>{c.drawImage(im,X,Y,W,H);if(t<524.7&&f.wartimeEyeReflection>0){const rx=X+f.wartimeEyeX*W,ry=Y+f.wartimeEyeY*H,cv=Object.assign(document.createElement('canvas'),{width:960,height:540});factory(cv.getContext('2d'),images,{...f,wartimeCameraX:0,wartimeCameraY:0,wartimeCameraZoom:0},523);layer(c,{...f,wartimeCameraX:0,wartimeCameraY:0,wartimeCameraZoom:0},'eye-reflection',t,[rx-r,ry-r*.65,r*2,r*1.3],(a,b,w,h)=>{c.beginPath();c.moveTo(-w/2,0);c.bezierCurveTo(-w*.22,-h*.65,w*.25,-h*.64,w/2,0);c.bezierCurveTo(w*.25,h*.55,-w*.25,h*.55,-w/2,0);c.closePath();c.clip();for(let j=0;j<32;j++){const u=j/32,bend=1-.14*Math.pow(u*2-1,2);c.drawImage(cv,u*960,0,30,540,-w/2+u*w,-h*bend/2,w/32+.8,h*bend);}const glint=c.createRadialGradient(-w*.2,-h*.18,0,-w*.2,-h*.18,w*.45);glint.addColorStop(0,'#ffffff77');glint.addColorStop(.12,'#ffffff22');glint.addColorStop(1,'#fff0');c.fillStyle=glint;c.fillRect(-w/2,-h/2,w,h);},{alpha:(1-span(t,524.1,524.7))*f.wartimeEyeReflection});}});if(t<523.15){c.save();c.globalAlpha*=1-span(t,523,523.15);factory(c,images,f,523);c.restore();}}
function flames(c,images,f,t,front=false){const strength=span(t,525.7,526.4)*f.wartimeFire;if(!strength)return;layer(c,f,front?'fire-front':'fire-back',t,[0,0,960,540],()=>{c.globalCompositeOperation='screen';for(let i=0;i<(front?2:3);i++){const frame=wartimeAtlasFrame(images,'wartFireFrame',((t-525.7)*24*f.wartimeFireMotionRate+i*37+(front?17:0))%144,6,4),W=front?720:850,H=W*270/480,X=(front?[-650,170]:[-850,-150,400])[i],Y=front?-20:-150;c.save();if(i%2){c.translate(2*X+W,0);c.scale(-1,1);}if(f.wartimeFullSources.wartFlame||f.wartimeSourceBindings.wartFlame){const im=image(images,f,'wartFlame');if(im)c.drawImage(im,X,Y,W,H);}else drawAtlas(c,frame,X,Y,W,H);c.restore();}},{alpha:strength*(front?.85:.95)});}

function fireScene(c,images,f,t){plate(c,images,f,'wartHall',t,1.45);flames(c,images,f,t);portrait(c,images,f,t,false);layer(c,f,'light',t,[0,0,960,540],(x,y,w,h)=>{const g=c.createLinearGradient(0,-270,0,270);g.addColorStop(0,'#ff750000');g.addColorStop(1,`rgba(255,90,10,${.18+.04*Math.sin(t*12)})`);c.globalCompositeOperation='screen';c.fillStyle=g;c.fillRect(x,y,w,h);},{alpha:span(t,525.7,526.6)*f.wartimeFire});flames(c,images,f,t,true);layer(c,f,'embers',t,[0,0,960,540],()=>{for(let i=0;i<35;i++){const x=(i*137+t*17)%960-480,y=270-((t*80+i*39)%650);c.fillStyle='#ffd075';c.globalAlpha*=.99;c.fillRect(x,y,1+i%2,3);}},{alpha:span(t,525.7,526.6)*f.wartimeFire});}
function burningHouse(c,images,f,t){plate(c,images,f,'wartHouse',t,1.08);flames(c,images,f,t,false);layer(c,f,'house-smoke',t,[0,0,960,540],(x,y,w,h)=>{const im=image(images,f,'wartSky');if(!im)return;c.globalAlpha*=.18;c.filter='grayscale(1) blur(8px)';c.drawImage(im,x-30,y-180,w+60,h);});flames(c,images,f,t,true);}
function family(c,images,f,t){const q=span(t,530.5,535),z=mix(2.7,1,q),depth=f.wartimeFamilyDepth;plate(c,images,f,'wartHouse',t,1.15-q*.1);if(f.wartimeFullSources.wartFamily||f.wartimeSourceBindings.wartFamily){sprite(c,images,f,'wartFamily',t,[480-420*z,270-300*z,840*z,0]);return;}layer(c,f,'wartFamily',t,[0,0,960,540],()=>{c.translate(-480,-270);const inner={...f,wartimeCameraX:0,wartimeCameraY:0,wartimeCameraZoom:0};for(const[id,cx,y,w,dep]of [['wartFamilyRear',190,175,260,.5],['wartFamilyTeen',430,180,140,.6],['wartFamilyMother',535,150,200,.8],['wartFamilyOlder',830,130,210,1],['wartFamilyBoy',490,270,175,3.8],['wartFamilyBoy2',655,285,160,1.1]]){const Z=1+(z-1)*dep*depth,im=image(images,f,id),base=im?Math.max(w,(560-y)*im.width/im.height):w,W=base*Z;sprite(c,images,inner,id,t,[480+(cx-480)*Z-W/2,mix(-80,y,q)+(y-270)*(Z-1)*.25,W,0]);}});}

export function paintWartime(c,age,images,input={}){const f={...wartimeDefaults,...input},state=wartimeState(age,f),t=state.source;if(age<0||!f.wartimeEnabled)return state;c.save();c.canvas.sceneAssets=[];c.fillStyle='#000';c.fillRect(0,0,960,540);if(t<482.3)title(c,images,f,t);else if(t<483.5){}else if(t<494.35)hall(c,images,f,t);else if(t<503.4)stadium(c,images,f,t);else if(t<506.4){stadium(c,images,f,Math.min(t,503.7));blast(c,images,f,t);}else if(t<510.4)aircraft(c,images,f,t);else if(t<518.1)exterior(c,images,f,t);else if(t<523)factory(c,images,f,t);else if(t<525.7)portrait(c,images,f,t);else if(t<529.5)fireScene(c,images,f,t);else if(t<530.5){burningHouse(c,images,f,t);}else family(c,images,f,t);if(t>=483.5){const g=c.createRadialGradient(480,260,180,480,270,640);g.addColorStop(0,'#0000');g.addColorStop(1,'#0009');c.fillStyle=g;c.fillRect(0,0,960,540);}c.fillStyle='#000';c.fillRect(0,0,960,f.wartimeLetterbox);c.fillRect(0,540-f.wartimeLetterbox,960,f.wartimeLetterbox);c.restore();return state;}
